BEGIN;
SELECT no_plan();
INSERT INTO auth.users(id,email,raw_app_meta_data) VALUES('14000000-0000-4000-8000-000000000001','application-review-owner@example.test','{"_invite_provisioned":true}'),('14000000-0000-4000-8000-000000000002','application-review-foreign@example.test','{"_invite_provisioned":true}');
CREATE TEMP TABLE app_tenants(label text,id uuid);
INSERT INTO app_tenants VALUES('own',(public.provision_company_atomic('14000000-0000-4000-8000-000000000001','{"name":"Application fixture","slug":"application-review-fixture","domain":"application-review.example.test"}')->>'id')::uuid),('foreign',(public.provision_company_atomic('14000000-0000-4000-8000-000000000002','{"name":"Foreign application fixture","slug":"foreign-application-review","domain":"foreign-application-review.example.test"}')->>'id')::uuid);
UPDATE public.users SET must_change_password=false WHERE auth_user_id IN('14000000-0000-4000-8000-000000000001','14000000-0000-4000-8000-000000000002');
INSERT INTO public.driver_applications(id,tenant_id,first_name,last_name,full_name,mobile,identity_type,work_type) SELECT ('14000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,id,'Synthetic','Candidate','Candidate fixture '||n,'0501400001','iqama','freelancer' FROM app_tenants CROSS JOIN generate_series(11,13)n WHERE label='own';
INSERT INTO public.driver_applications(id,tenant_id,first_name,last_name,full_name,mobile,identity_type,work_type) SELECT md5('application-page-'||n)::uuid,id,'Paged','Candidate','Paged candidate '||n,'0501400001','iqama','freelancer' FROM app_tenants CROSS JOIN generate_series(1,1005)n WHERE label='own';
CREATE TEMP TABLE app_results(label text PRIMARY KEY,result jsonb);GRANT ALL ON app_results,app_tenants TO authenticated,service_role;
SELECT ok(NOT has_function_privilege('service_role','public.decide_application_atomic(uuid,uuid,text,text,uuid)','execute'),'legacy service application decision is retired');
SELECT ok(NOT has_function_privilege('service_role','public.decide_leave_request_atomic(uuid,uuid,text,text,uuid)','execute'),'legacy service leave decision is retired');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"14000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
SELECT is((public.fetch_applications_page('Paged candidate')->>'total')::int,1005,'filtered count exceeds old200 and API1000 ceilings');
SELECT is(jsonb_array_length(public.fetch_applications_page('Paged candidate','all',false,11,100)->'rows'),5,'last page beyond1000 remains reachable');
SELECT is((public.fetch_applications_page('%_')->>'total')::int,0,'search treats wildcard characters literally');
SELECT throws_ok($$UPDATE public.driver_applications SET status='approved' WHERE id='14000000-0000-4000-8000-000000000011'$$,'42501',NULL,'direct client approval cannot bypass review workflow');
INSERT INTO app_results VALUES('review',public.mutate_application_review_atomic('14000000-0000-4000-8000-000000000011',1,'under_review','Begin document review'));
SELECT is((SELECT result->>'status' FROM app_results WHERE label='review'),'under_review','pending review transition is persisted');
RESET ROLE;
INSERT INTO public.driver_application_documents(application_id,tenant_id,document_type,file_name,storage_path) SELECT '14000000-0000-4000-8000-000000000011',id,'identity','synthetic.pdf',id||'/synthetic.pdf' FROM app_tenants WHERE label='own';
SELECT is((SELECT workflow_version FROM public.driver_applications WHERE id='14000000-0000-4000-8000-000000000011'),3,'changed document evidence invalidates the reviewed version');
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.mutate_application_review_atomic('14000000-0000-4000-8000-000000000011',2,'approved','Approve stale evidence')$$,'P0001','APP_STALE','reviewer cannot approve changed document evidence');
UPDATE app_results SET result=public.mutate_application_review_atomic('14000000-0000-4000-8000-000000000011',3,'approved','Approve current evidence') WHERE label='review';
SELECT is((SELECT status FROM public.driver_applications WHERE id='14000000-0000-4000-8000-000000000011'),'approved','current reviewed evidence can be approved');
SELECT throws_ok($$SELECT public.mutate_application_review_atomic('14000000-0000-4000-8000-000000000011',4,'rejected','Overwrite final review')$$,'P0001','APP002: application already decided','a final decision cannot be overwritten');
INSERT INTO app_results VALUES('withdraw',public.mutate_application_review_atomic('14000000-0000-4000-8000-000000000012',1,'withdraw','Withdraw pending application'));
UPDATE app_results SET result=public.mutate_application_review_atomic('14000000-0000-4000-8000-000000000012',(result->>'version')::int,'archive','Archive final application') WHERE label='withdraw';
SELECT is((public.fetch_applications_page('','all',true)->>'total')::int,1,'archive is a visibility change with retained final history');
UPDATE app_results SET result=public.mutate_application_review_atomic('14000000-0000-4000-8000-000000000012',(result->>'version')::int,'restore','Restore final history visibility') WHERE label='withdraw';
SELECT is((SELECT status FROM public.driver_applications WHERE id='14000000-0000-4000-8000-000000000012'),'withdrawn','restore never resurrects a final application as pending');
SELECT is((public.fetch_applications_page()->'summary'->>'withdrawn')::int,1,'summary includes withdrawn history independently of current page');
RESET ROLE;
SELECT throws_ok($$UPDATE public.driver_applications SET full_name='Rewrite final identity' WHERE id='14000000-0000-4000-8000-000000000011'$$,'P0001','APP_HISTORY_IMMUTABLE','trusted direct rewrite cannot alter final personal data');
SELECT throws_ok($$INSERT INTO public.driver_application_documents(application_id,tenant_id,document_type,file_name,storage_path) SELECT '14000000-0000-4000-8000-000000000011',id,'license','later.pdf',id||'/later.pdf' FROM app_tenants WHERE label='own'$$,'P0001','APP_HISTORY_IMMUTABLE','final document evidence is immutable');
CREATE FUNCTION pg_temp.fail_application_review_audit() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.action='application_reviewed' THEN RAISE EXCEPTION 'Synthetic application audit fault';END IF;RETURN NEW;END;$$;
CREATE TRIGGER fail_application_review_audit BEFORE INSERT ON public.audit_log FOR EACH ROW EXECUTE FUNCTION pg_temp.fail_application_review_audit();
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.mutate_application_review_atomic('14000000-0000-4000-8000-000000000013',1,'rejected','Reject rollback fixture')$$,'P0001','Synthetic application audit fault','audit failure aborts the decision');
SELECT is((SELECT status FROM public.driver_applications WHERE id='14000000-0000-4000-8000-000000000013'),'submitted','failed audit leaves pending source intact');
SELECT is((SELECT workflow_version FROM public.driver_applications WHERE id='14000000-0000-4000-8000-000000000013'),1,'failed audit leaves reviewed version intact');
SELECT set_config('request.jwt.claims','{"sub":"14000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
SELECT is((public.fetch_applications_page()->>'total')::int,0,'foreign tenant cannot enumerate applications');
SELECT throws_ok($$SELECT public.mutate_application_review_atomic('14000000-0000-4000-8000-000000000013',1,'rejected','Foreign tenant decision')$$,'P0001','APP001: application not found','foreign tenant decision is denied');
SELECT set_config('request.jwt.claims','{"sub":"14000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
SELECT throws_ok($$SELECT public.fetch_applications_page()$$,'42501','APP_FORBIDDEN','privileged owner requires MFA for application pages');
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT throws_ok($$UPDATE public.driver_applications SET status='approved' WHERE id='14000000-0000-4000-8000-000000000013'$$,'42501','APP_CALLER_REQUIRED','legacy service update cannot bypass review and audit');
RESET ROLE;
SET LOCAL ROLE anon;
SELECT throws_ok($$SELECT public.fetch_applications_page()$$,'42501',NULL,'anonymous application list is denied');
RESET ROLE;
SELECT * FROM finish();ROLLBACK;
